using MediaBrowser.Model.Plugins;

namespace Jellyfin.Plugin.FinnishMetadata.Configuration;

public class PluginConfiguration : BasePluginConfiguration
{
    public bool EnableYleAreena { get; set; } = true;
    public bool EnableRuutu { get; set; } = true;
    public bool EnableKatsomo { get; set; } = true;

    /// <summary>
    /// Reads &lt;episode_filename&gt;.txt generated by FlickFetch for episode descriptions.
    /// </summary>
    public bool ReadFlickFetchTxtSidecar { get; set; } = true;

    /// <summary>
    /// If true, prefers the local FlickFetch .txt synopsis over the remote web overview.
    /// </summary>
    public bool PreferLocalTxtOverRemote { get; set; } = true;

    /// <summary>
    /// Optional official Yle API credentials (if empty, uses public Areena JSON-LD/web search).
    /// </summary>
    public string YleAppId { get; set; } = string.Empty;
    public string YleAppKey { get; set; } = string.Empty;
}
